# Try simple downsampling: output[r][c] comes from input at some formula

def try_downsampling(seq_in, seq_out, factor=10):
    """Check if seq_out[r] = seq_in[r*factor]"""
    n_out = len(seq_out)
    for r in range(n_out):
        in_idx = r * factor
        if in_idx >= len(seq_in):
            return False, f"r={r}: idx={in_idx} >= len({len(seq_in)})"
        if seq_out[r] != seq_in[in_idx]:
            return False, f"r={r}: {seq_out[r]} != {seq_in[in_idx]}"
    return True, "match"

